with changes(course_slug,lesson_no,patch) as (values
 ('introligator-tradycja',11,$data${"learning":{"task":"Narysuj trzy widoki notesu, arkusz impozycji 16 stron, tabelę wszystkich materiałów, rozstaw punktów szycia i protokół jakości zawierający co najmniej 10 kryteriów. Dodaj analizę przyczyny źle pracującej okładki oraz propozycję kontroli zapobiegawczej.","intro":"Przygotuj projekt notesu z 64 stronami w czterech składkach po 16 stron. Każda składka to cztery arkusze złożone raz. Docelowy format jest umowny, np. A5; sprawdź sposób składania arkuszy, margines przy grzbiecie, rozstaw punktów szycia i dobór okładki.","correct":2,"example":"16 arkuszy","options":["64 arkusze","32 arkusze","16 arkuszy","4 arkusze"],"feedback":["Sprawdź obliczenie. Podziel 64 strony przez 4 strony na arkusz. Otrzymasz 16 arkuszy bloku.","Sprawdź obliczenie. Podziel 64 strony przez 4 strony na arkusz. Otrzymasz 16 arkuszy bloku.","Dobrze. Podziel 64 strony przez 4 strony na arkusz. Otrzymasz 16 arkuszy bloku.","Sprawdź obliczenie. Podziel 64 strony przez 4 strony na arkusz. Otrzymasz 16 arkuszy bloku."],"question":"W projekcie 64-stronicowego notesu złożonego z arkuszy po cztery strony — ile potrzeba arkuszy przed złożeniem?","situation":"Przed zszyciem planujesz 64 strony notesu. Każdy arkusz po złożeniu daje cztery strony. Załóż, że okładkę liczysz osobno.","explanation":"Podziel 64 strony przez 4 strony na arkusz. Otrzymasz 16 arkuszy bloku."}}$data$::jsonb),
 ('ludwisarz',6,$data${"learning":{"task":"Sporządź na papierze analizę SJA dziesięciu zagrożeń: ryzyko, prewencja, odpowiedzialny, decyzja.","intro":"Woda we wsadzie lub formie może gwałtownie zamienić się w parę i rozprysnąć ciekły metal. Praktyka wymaga wykwalifikowanej załogi, planu awaryjnego i kontroli stanowiska.","correct":0,"example":"Może spowodować gwałtowny rozprysk przez parę.","options":["Może spowodować gwałtowny rozprysk przez parę.","Zmienia wyłącznie kolor metalu.","Automatycznie zmniejsza masę odlewu.","Zastępuje odpowietrzenie formy."],"feedback":["Dobrze. Wilgoć w kontakcie z ciekłym metalem może gwałtownie wytworzyć parę i rozrzucić metal. Zatrzymaj pracę i zgłoś ryzyko prowadzącemu.","Sprawdź zasadę. Wilgoć w kontakcie z ciekłym metalem może gwałtownie wytworzyć parę i rozrzucić metal. Zatrzymaj pracę i zgłoś ryzyko prowadzącemu.","Sprawdź zasadę. Wilgoć w kontakcie z ciekłym metalem może gwałtownie wytworzyć parę i rozrzucić metal. Zatrzymaj pracę i zgłoś ryzyko prowadzącemu.","Sprawdź zasadę. Wilgoć w kontakcie z ciekłym metalem może gwałtownie wytworzyć parę i rozrzucić metal. Zatrzymaj pracę i zgłoś ryzyko prowadzącemu."],"question":"Dlaczego wilgotny wsad jest zagrożeniem?","situation":"W zakładzie znaleziono wilgotny wsad po deszczu. Pracę należy wstrzymać i zgłosić problem.","explanation":"Wilgoć w kontakcie z ciekłym metalem może gwałtownie wytworzyć parę i rozrzucić metal. Zatrzymaj pracę i zgłoś ryzyko prowadzącemu."},"illustration":"ludwisarz-bhp"}$data$::jsonb),
 ('ludwisarz',7,$data${"learning":{"task":"Na schemacie przekroju narysuj cztery wady i kartę kontroli ośmiu fikcyjnych odlewów.","intro":"Wady odlewu to różne nieciągłości: pory, pustki skurczowe, wtrącenia i pęknięcia. Gładka powierzchnia nie gwarantuje braku wad wewnętrznych.","correct":1,"example":"Porowatość wewnętrzna.","options":["Wypukły napis.","Porowatość wewnętrzna.","Dekoracja zewnętrzna.","Ślad narzędzia na zewnątrz."],"feedback":["Sprawdź zasadę. Polerowanie zmienia powierzchnię, a wewnętrzna nieciągłość może pozostać ukryta. Dobór badania i ocenę wyniku zleca się kompetentnej osobie.","Dobrze. Polerowanie zmienia powierzchnię, a wewnętrzna nieciągłość może pozostać ukryta. Dobór badania i ocenę wyniku zleca się kompetentnej osobie.","Sprawdź zasadę. Polerowanie zmienia powierzchnię, a wewnętrzna nieciągłość może pozostać ukryta. Dobór badania i ocenę wyniku zleca się kompetentnej osobie.","Sprawdź zasadę. Polerowanie zmienia powierzchnię, a wewnętrzna nieciągłość może pozostać ukryta. Dobór badania i ocenę wyniku zleca się kompetentnej osobie."],"question":"Co może pozostać niewidoczne po polerowaniu?","situation":"Odlew ma idealny wygląd, ale badanie wykazało pustkę. Należy udokumentować wskazanie i ocenić według kryteriów.","explanation":"Polerowanie zmienia powierzchnię, a wewnętrzna nieciągłość może pozostać ukryta. Dobór badania i ocenę wyniku zleca się kompetentnej osobie."},"illustration":"ludwisarz-wady"}$data$::jsonb),
 ('ludwisarz',8,$data${"learning":{"task":"Narysuj wykres pięciu składowych i oblicz stosunek nominal/prime.","intro":"Dzwon wytwarza kilka rezonansów. Analizuje się hum, prime, tierce, quint i nominal. Proporcje zależą od profilu i stopu, a nie wyłącznie średnicy.","correct":2,"example":"1000 Hz.","options":["750 Hz.","250 Hz.","1000 Hz.","1500 Hz."],"feedback":["Sprawdź zasadę. Oktawa w górę oznacza podwojenie częstotliwości. Dla modelowych 500 Hz jest to 1000 Hz.","Sprawdź zasadę. Oktawa w górę oznacza podwojenie częstotliwości. Dla modelowych 500 Hz jest to 1000 Hz.","Dobrze. Oktawa w górę oznacza podwojenie częstotliwości. Dla modelowych 500 Hz jest to 1000 Hz.","Sprawdź zasadę. Oktawa w górę oznacza podwojenie częstotliwości. Dla modelowych 500 Hz jest to 1000 Hz."],"question":"Jeżeli prime=500 Hz, nominal oktawę wyżej ma...","situation":"Model prime=500 Hz, hum=250 Hz, nominal=1000 Hz, quint około 750 Hz i tierce około 600 Hz jest wyłącznie dydaktyczny.","explanation":"Oktawa w górę oznacza podwojenie częstotliwości. Dla modelowych 500 Hz jest to 1000 Hz."},"illustration":"ludwisarz-akustyka"}$data$::jsonb),
 ('ludwisarz',9,$data${"learning":{"task":"Ułóż tabelę pięciu składowych: cel, pomiar, różnica, decyzja, brakujące dane. Nie obrabiaj metalu.","intro":"Strojenie polega na analizie rezonansów i fachowej zmianie profilu. Usunięcie metalu może inaczej wpłynąć na różne składowe i nie jest odwracalne.","correct":0,"example":"Bo skrawanie może zmienić wiele rezonansów.","options":["Bo skrawanie może zmienić wiele rezonansów.","Bo dzwon ma tylko jedną składową.","Bo częstotliwości nie da się zmierzyć.","Bo skrawanie nigdy nie zmienia profilu."],"feedback":["Dobrze. Zmiana profilu może zmienić kilka rezonansów w różnym stopniu. Porównaj całe widmo i przekaż dane fachowcowi przed decyzją o ingerencji.","Sprawdź zasadę. Zmiana profilu może zmienić kilka rezonansów w różnym stopniu. Porównaj całe widmo i przekaż dane fachowcowi przed decyzją o ingerencji.","Sprawdź zasadę. Zmiana profilu może zmienić kilka rezonansów w różnym stopniu. Porównaj całe widmo i przekaż dane fachowcowi przed decyzją o ingerencji.","Sprawdź zasadę. Zmiana profilu może zmienić kilka rezonansów w różnym stopniu. Porównaj całe widmo i przekaż dane fachowcowi przed decyzją o ingerencji."],"question":"Dlaczego pomiar jedynie prime nie wystarcza do strojenia?","situation":"Prime docelowe 500 Hz, zmierzone 493 Hz: różnica +7 Hz. Nominal 1000 vs 992 Hz: +8 Hz. Nie wynika z tego miejsce skrawania.","explanation":"Zmiana profilu może zmienić kilka rezonansów w różnym stopniu. Porównaj całe widmo i przekaż dane fachowcowi przed decyzją o ingerencji."},"illustration":"ludwisarz-akustyka"}$data$::jsonb),
 ('ludwisarz',10,$data${"learning":{"task":"Narysuj tor sił i wskaż brakujące parametry do projektu zawieszenia.","intro":"Zawieszenie przenosi ciężar i obciążenia dynamiczne. Sama masa nie określa nośności korony, jarzma, ramy i zamocowań.","correct":1,"example":"Bo dochodzą obciążenia dynamiczne.","options":["Bo nie ma grawitacji.","Bo dochodzą obciążenia dynamiczne.","Bo liczy się tylko kolor stopu.","Bo masa nie wpływa na siły."],"feedback":["Sprawdź zasadę. Około 1962 N opisuje statyczny ciężar 200 kg w tym przykładzie. Ruch i uderzenia powodują dodatkowe obciążenia, które trzeba uwzględnić w projekcie zawieszenia.","Dobrze. Około 1962 N opisuje statyczny ciężar 200 kg w tym przykładzie. Ruch i uderzenia powodują dodatkowe obciążenia, które trzeba uwzględnić w projekcie zawieszenia.","Sprawdź zasadę. Około 1962 N opisuje statyczny ciężar 200 kg w tym przykładzie. Ruch i uderzenia powodują dodatkowe obciążenia, które trzeba uwzględnić w projekcie zawieszenia.","Sprawdź zasadę. Około 1962 N opisuje statyczny ciężar 200 kg w tym przykładzie. Ruch i uderzenia powodują dodatkowe obciążenia, które trzeba uwzględnić w projekcie zawieszenia."],"question":"Dlaczego 1962 N nie wystarcza do projektu mocowania dzwonu ruchomego?","situation":"Dla 200 kg statyczny ciężar to około 1962 N. Kołysanie i uderzenia wymagają dodatkowej analizy konstrukcji.","explanation":"Około 1962 N opisuje statyczny ciężar 200 kg w tym przykładzie. Ruch i uderzenia powodują dodatkowe obciążenia, które trzeba uwzględnić w projekcie zawieszenia."},"illustration":"ludwisarz-anatomia"}$data$::jsonb),
 ('ludwisarz',11,$data${"learning":{"task":"Oddaj przekrój, trzy obliczenia, kartę dziesięciu ryzyk i protokół oceny wad. Wyjaśnij, czego nie można wywnioskować.","intro":"Projekt dydaktyczny obejmuje profil, skład, geometrię formy, wady, akustykę i ryzyka. Nie jest projektem odlewniczym ani dopuszczeniem do montażu.","correct":2,"example":"6,6 kg.","options":["23,4 kg.","7,8 kg.","6,6 kg.","22 kg."],"feedback":["Sprawdź zasadę. 22% z 30 kg to 0,22 × 30 = 6,6 kg cyny. W modelowym stopie pozostałe 23,4 kg stanowi miedź.","Sprawdź zasadę. 22% z 30 kg to 0,22 × 30 = 6,6 kg cyny. W modelowym stopie pozostałe 23,4 kg stanowi miedź.","Dobrze. 22% z 30 kg to 0,22 × 30 = 6,6 kg cyny. W modelowym stopie pozostałe 23,4 kg stanowi miedź.","Sprawdź zasadę. 22% z 30 kg to 0,22 × 30 = 6,6 kg cyny. W modelowym stopie pozostałe 23,4 kg stanowi miedź."],"question":"Ile cyny w modelowych 30 kg stopu o udziale 22% Sn?","situation":"30 kg stopu 78% Cu i 22% Sn to nominalnie 23,4 kg Cu i 6,6 kg Sn. Dla średnic 240/210 mm ścianka ma 15 mm.","explanation":"22% z 30 kg to 0,22 × 30 = 6,6 kg cyny. W modelowym stopie pozostałe 23,4 kg stanowi miedź."},"illustration":"ludwisarz-stop"}$data$::jsonb),
 ('mlynarz-tradycyjny',0,$data${"learning":{"task":"Narysuj przekrój ziarna, podpisz trzy części i sporządź kartę przyjęcia partii.","correct":0,"example":"Bielmo, okrywy, zarodek.","options":["Bielmo, okrywy, zarodek.","Bielmo, popiół, gluten jako organy.","Kora, rdzeń i łodyga.","Piasta, okrywa i zarodek."],"feedback":["Dobrze. Bielmo dostarcza głównie skrobi, okrywy osłaniają ziarno, a zarodek daje początek nowej roślinie. Te trzy części rozpoznasz na przekroju.","Sprawdź zasadę. Bielmo dostarcza głównie skrobi, okrywy osłaniają ziarno, a zarodek daje początek nowej roślinie. Te trzy części rozpoznasz na przekroju.","Sprawdź zasadę. Bielmo dostarcza głównie skrobi, okrywy osłaniają ziarno, a zarodek daje początek nowej roślinie. Te trzy części rozpoznasz na przekroju.","Sprawdź zasadę. Bielmo dostarcza głównie skrobi, okrywy osłaniają ziarno, a zarodek daje początek nowej roślinie. Te trzy części rozpoznasz na przekroju."],"question":"Co jest głównymi częściami ziarna?","situation":"Na stole leżą dwa przekroje ziaren pszenicy. Na schemacie trzeba wskazać część bogatą w skrobię, warstwy zewnętrzne oraz część, z której rozwija się nowa roślina.","explanation":"Bielmo dostarcza głównie skrobi, okrywy osłaniają ziarno, a zarodek daje początek nowej roślinie. Te trzy części rozpoznasz na przekroju."}}$data$::jsonb),
 ('mlynarz-tradycyjny',1,$data${"learning":{"task":"Zaprojektuj proces od przyjęcia do młyna, dobierz separację metalu, kamieni, plew i pyłu.","correct":1,"example":"Odseparować zanieczyszczenia i ocenić partię.","options":["Zwiększyć obroty.","Odseparować zanieczyszczenia i ocenić partię.","Zalać wodą, aby zmiękły.","Pominąć, jeśli śruby są małe."],"feedback":["Sprawdź zasadę. Stalowa śruba jest obcym materiałem. Wstrzymaj kierowanie partii do przemiału, odseparuj ją i przekaż do kontroli zgodnie z procedurą zakładu.","Dobrze. Stalowa śruba jest obcym materiałem. Wstrzymaj kierowanie partii do przemiału, odseparuj ją i przekaż do kontroli zgodnie z procedurą zakładu.","Sprawdź zasadę. Stalowa śruba jest obcym materiałem. Wstrzymaj kierowanie partii do przemiału, odseparuj ją i przekaż do kontroli zgodnie z procedurą zakładu.","Sprawdź zasadę. Stalowa śruba jest obcym materiałem. Wstrzymaj kierowanie partii do przemiału, odseparuj ją i przekaż do kontroli zgodnie z procedurą zakładu."],"question":"W partii są stalowe śruby. Co zrobić?","situation":"Przy kontroli partii przed przemiałem znalazłeś stalowe śruby. Partia jest jeszcze oddzielona od surowca przeznaczonego do dalszej pracy.","explanation":"Stalowa śruba jest obcym materiałem. Wstrzymaj kierowanie partii do przemiału, odseparuj ją i przekaż do kontroli zgodnie z procedurą zakładu."}}$data$::jsonb),
 ('mlynarz-tradycyjny',2,$data${"learning":{"task":"Narysuj przekrój młyna od kosza do worka i podpisz wszystkie sześć części.","correct":2,"example":"Bedstone.","options":["Runner.","Damsel.","Bedstone.","Hopper."],"feedback":["Sprawdź zasadę. Oddziel elementy ruchome, nieruchome i służące do podawania. Nie myl żłobienia roboczego z pęknięciem kamienia.","Sprawdź zasadę. Oddziel elementy ruchome, nieruchome i służące do podawania. Nie myl żłobienia roboczego z pęknięciem kamienia.","Dobrze. Oddziel elementy ruchome, nieruchome i służące do podawania. Nie myl żłobienia roboczego z pęknięciem kamienia.","Sprawdź zasadę. Oddziel elementy ruchome, nieruchome i służące do podawania. Nie myl żłobienia roboczego z pęknięciem kamienia."],"question":"Który kamień zwykle jest nieruchomy?","situation":"Oglądasz zatrzymany przekrój młyna. Ziarno opada do środka pary kamieni. Opisz, który kamień przenosi ruch, a który pozostaje nieruchomy.","explanation":"Oddziel elementy ruchome, nieruchome i służące do podawania. Nie myl żłobienia roboczego z pęknięciem kamienia."}}$data$::jsonb),
 ('mlynarz-tradycyjny',3,$data${"learning":{"task":"Narysuj wał i stone nut. Policz także wariant 60 zębów do 20 przy 12 obr./min.","correct":3,"example":"48 obr./min.","options":["3 obr./min.","12 obr./min.","24 obr./min.","48 obr./min."],"feedback":["Sprawdź zasadę. Koło 72-zębne z prędkością 12 obr./min napędza koło 18-zębne: 12×72/18=48 obr./min w uproszczonym modelu.","Sprawdź zasadę. Koło 72-zębne z prędkością 12 obr./min napędza koło 18-zębne: 12×72/18=48 obr./min w uproszczonym modelu.","Sprawdź zasadę. Koło 72-zębne z prędkością 12 obr./min napędza koło 18-zębne: 12×72/18=48 obr./min w uproszczonym modelu.","Dobrze. Koło 72-zębne z prędkością 12 obr./min napędza koło 18-zębne: 12×72/18=48 obr./min w uproszczonym modelu."],"question":"72 zęby, 12 obr./min, napęd 18 zębów. Ile obrotów ma koło wyjściowe?","situation":"Na schemacie koło napędzające ma 72 zęby i obraca się 12 razy na minutę. Zazębia się z kołem wyjściowym o 18 zębach. Oblicz prędkość w modelu idealnym.","explanation":"Koło 72-zębne z prędkością 12 obr./min napędza koło 18-zębne: 12×72/18=48 obr./min w uproszczonym modelu."}}$data$::jsonb),
 ('mlynarz-tradycyjny',4,$data${"learning":{"task":"Narysuj przekrój powierzchni i tabelę czterech objawów z hipotezami i kontrolą.","correct":0,"example":"Liczy się też geometria rowków i stan powierzchni.","options":["Liczy się też geometria rowków i stan powierzchni.","Bo rowki nie wpływają na przemiał.","Bo dolny zawsze obraca się szybciej.","Bo ważny jest tylko kolor osłony."],"feedback":["Dobrze. Przy kontroli trzeba rozróżniać zaprojektowane rowki od pęknięć. Podnoszenie ciężkiego runner oraz jego dressing należy do prac fachowych.","Sprawdź zasadę. Przy kontroli trzeba rozróżniać zaprojektowane rowki od pęknięć. Podnoszenie ciężkiego runner oraz jego dressing należy do prac fachowych.","Sprawdź zasadę. Przy kontroli trzeba rozróżniać zaprojektowane rowki od pęknięć. Podnoszenie ciężkiego runner oraz jego dressing należy do prac fachowych.","Sprawdź zasadę. Przy kontroli trzeba rozróżniać zaprojektowane rowki od pęknięć. Podnoszenie ciężkiego runner oraz jego dressing należy do prac fachowych."],"question":"Dlaczego sama średnica kamienia nie wystarcza do oceny jakości?","situation":"Dwa kamienie mają tę samą średnicę. Na pierwszym rowki są wyraźne, a na drugim widać zużyte powierzchnie. Musisz wyjaśnić, co jeszcze trzeba ocenić.","explanation":"Przy kontroli trzeba rozróżniać zaprojektowane rowki od pęknięć. Podnoszenie ciężkiego runner oraz jego dressing należy do prac fachowych."}}$data$::jsonb),
 ('mlynarz-tradycyjny',5,$data${"learning":{"task":"Policz wyciąg dla 150/200 i 180/200; opisz różnice składu frakcji.","correct":1,"example":"75%.","options":["50%.","75%.","90%.","125%."],"feedback":["Sprawdź zasadę. Ze 200 kg ziarna otrzymano 150 kg mąki: 75% wyciągu. Bilans może obejmować 48 kg innych frakcji i 2 kg strat; 150+48+2=200.","Dobrze. Ze 200 kg ziarna otrzymano 150 kg mąki: 75% wyciągu. Bilans może obejmować 48 kg innych frakcji i 2 kg strat; 150+48+2=200.","Sprawdź zasadę. Ze 200 kg ziarna otrzymano 150 kg mąki: 75% wyciągu. Bilans może obejmować 48 kg innych frakcji i 2 kg strat; 150+48+2=200.","Sprawdź zasadę. Ze 200 kg ziarna otrzymano 150 kg mąki: 75% wyciągu. Bilans może obejmować 48 kg innych frakcji i 2 kg strat; 150+48+2=200."],"question":"Jaki jest wyciąg 150 kg mąki z 200 kg ziarna?","situation":"W karcie próbnego przemiału zapisano 200 kg oczyszczonego ziarna. Odebrano 150 kg mąki, a pozostałe frakcje i straty zapisano osobno.","explanation":"Ze 200 kg ziarna otrzymano 150 kg mąki: 75% wyciągu. Bilans może obejmować 48 kg innych frakcji i 2 kg strat; 150+48+2=200."}}$data$::jsonb),
 ('mlynarz-tradycyjny',6,$data${"learning":{"task":"Narysuj rozdział mąki na sita i policz wskaźnik popiołu oraz wyciągu dla innych danych.","correct":2,"example":"0,55%.","options":["0,055%.","0,11%.","0,55%.","5,5%."],"feedback":["Sprawdź zasadę. Próbka 10 g pozostawia 0,055 g popiołu: 0,055/10×100%=0,55%. Porównania wymagają uzgodnionej metody i podstawy wilgotności.","Sprawdź zasadę. Próbka 10 g pozostawia 0,055 g popiołu: 0,055/10×100%=0,55%. Porównania wymagają uzgodnionej metody i podstawy wilgotności.","Dobrze. Próbka 10 g pozostawia 0,055 g popiołu: 0,055/10×100%=0,55%. Porównania wymagają uzgodnionej metody i podstawy wilgotności.","Sprawdź zasadę. Próbka 10 g pozostawia 0,055 g popiołu: 0,055/10×100%=0,55%. Porównania wymagają uzgodnionej metody i podstawy wilgotności."],"question":"Popiół 0,055 g z próbki 10 g to...","situation":"Porównujesz wyniki badań mąki wykonane tą samą metodą. Jedna próbka miała 10 g, a po oznaczeniu pozostało 0,055 g popiołu.","explanation":"Próbka 10 g pozostawia 0,055 g popiołu: 0,055/10×100%=0,55%. Porównania wymagają uzgodnionej metody i podstawy wilgotności."}}$data$::jsonb),
 ('mlynarz-tradycyjny',7,$data${"learning":{"task":"Przygotuj SJA z 10 zagrożeniami, kontrolą prac elektrycznych i sposobem bezpiecznego usuwania pyłu.","correct":3,"example":"Bo powstaje potencjalnie zapalna chmura pyłu.","options":["Bo mąka jest niepalna.","Bo pył zamienia się w metal.","Bo wiatr neutralizuje zapłon.","Bo powstaje potencjalnie zapalna chmura pyłu."],"feedback":["Sprawdź zasadę. Zdmuchnięcie osadu może rozproszyć palny pył w powietrzu. W obecności źródła zapłonu taka chmura jest zagrożeniem. Zastosuj zasady sprzątania i odpylania ustalone dla stanowiska.","Sprawdź zasadę. Zdmuchnięcie osadu może rozproszyć palny pył w powietrzu. W obecności źródła zapłonu taka chmura jest zagrożeniem. Zastosuj zasady sprzątania i odpylania ustalone dla stanowiska.","Sprawdź zasadę. Zdmuchnięcie osadu może rozproszyć palny pył w powietrzu. W obecności źródła zapłonu taka chmura jest zagrożeniem. Zastosuj zasady sprzątania i odpylania ustalone dla stanowiska.","Dobrze. Zdmuchnięcie osadu może rozproszyć palny pył w powietrzu. W obecności źródła zapłonu taka chmura jest zagrożeniem. Zastosuj zasady sprzątania i odpylania ustalone dla stanowiska."],"question":"Dlaczego zdmuchiwanie osadzonej mąki może zwiększyć ryzyko?","situation":"Przy przeglądzie młyna widać warstwę pyłu mącznego. Ktoś chce zdmuchnąć ją do powietrza, aby szybko uporządkować pomieszczenie. Oceń ryzyko tej decyzji.","explanation":"Zdmuchnięcie osadu może rozproszyć palny pył w powietrzu. W obecności źródła zapłonu taka chmura jest zagrożeniem. Zastosuj zasady sprzątania i odpylania ustalone dla stanowiska."}}$data$::jsonb),
 ('mlynarz-tradycyjny',8,$data${"learning":{"task":"Przygotuj kartę magazynową dwóch partii: data, gatunek, masa, wilgotność, temperatura, lokalizacja, obserwacje, wynik kontroli i decyzja. Pokaż, co robisz przy oznakach samonagrzewania bez wchodzenia do wnętrza silosu.","correct":2,"example":"Wilgotność, temperatura, gatunek i czas składowania.","options":["Wyłącznie kolor worka.","Tylko liczba pracowników zmiany.","Wilgotność, temperatura, gatunek i czas składowania.","Sama cena zakupu ziarna."],"feedback":["Sprawdź zasadę. W przykładowej partii 1000 kg ziarna zmierzono 14% wilgotności metodą uzgodnioną dla produktu, a w innej 18%. Nie wolno wywnioskować wyłącznie z masy, że oba zapasy można bezpiecznie przechowywać identycznie. Potrzebne są wymagania dla gatunku, temperatura, historia partii i czas.","Sprawdź zasadę. W przykładowej partii 1000 kg ziarna zmierzono 14% wilgotności metodą uzgodnioną dla produktu, a w innej 18%. Nie wolno wywnioskować wyłącznie z masy, że oba zapasy można bezpiecznie przechowywać identycznie. Potrzebne są wymagania dla gatunku, temperatura, historia partii i czas.","Dobrze. W przykładowej partii 1000 kg ziarna zmierzono 14% wilgotności metodą uzgodnioną dla produktu, a w innej 18%. Nie wolno wywnioskować wyłącznie z masy, że oba zapasy można bezpiecznie przechowywać identycznie. Potrzebne są wymagania dla gatunku, temperatura, historia partii i czas.","Sprawdź zasadę. W przykładowej partii 1000 kg ziarna zmierzono 14% wilgotności metodą uzgodnioną dla produktu, a w innej 18%. Nie wolno wywnioskować wyłącznie z masy, że oba zapasy można bezpiecznie przechowywać identycznie. Potrzebne są wymagania dla gatunku, temperatura, historia partii i czas."],"question":"Która informacja pomaga ocenić ryzyko przechowywania ziarna?","situation":"Dwie partie zboża mają po 1000 kg. Różnią się wilgotnością i będą leżały w różnych temperaturach. Ustal, co trzeba wiedzieć przed podjęciem decyzji o składowaniu.","explanation":"W przykładowej partii 1000 kg ziarna zmierzono 14% wilgotności metodą uzgodnioną dla produktu, a w innej 18%. Nie wolno wywnioskować wyłącznie z masy, że oba zapasy można bezpiecznie przechowywać identycznie. Potrzebne są wymagania dla gatunku, temperatura, historia partii i czas."}}$data$::jsonb),
 ('mlynarz-tradycyjny',9,$data${"learning":{"task":"Zaprojektuj kartę jakości mąki dla piekarni: partia, gatunek, wilgotność, popiół, parametry białka lub glutenu według rodzaju mąki, wynik próby i decyzja. Zaznacz trzy informacje, których nie da się ustalić tylko wzrokiem.","correct":1,"example":"Bo liczą się także właściwości funkcjonalne, gatunek i wymagania produktu.","options":["Bo białko nie ma żadnego znaczenia w pieczeniu.","Bo liczą się także właściwości funkcjonalne, gatunek i wymagania produktu.","Bo każde zboże zawiera identyczną jakość glutenu.","Bo kolor opakowania rozstrzyga o wypieku."],"feedback":["Sprawdź zasadę. Partia A ma 11% białka, partia B 13%. Sam procent białka nie wystarcza do uznania B za lepszą do każdego chleba: potrzebne są cechy funkcjonalne, warunki testu i oczekiwany produkt. Przy odbiorze rozróżnij badanie laboratoryjne od oceny wizualnej.","Dobrze. Partia A ma 11% białka, partia B 13%. Sam procent białka nie wystarcza do uznania B za lepszą do każdego chleba: potrzebne są cechy funkcjonalne, warunki testu i oczekiwany produkt. Przy odbiorze rozróżnij badanie laboratoryjne od oceny wizualnej.","Sprawdź zasadę. Partia A ma 11% białka, partia B 13%. Sam procent białka nie wystarcza do uznania B za lepszą do każdego chleba: potrzebne są cechy funkcjonalne, warunki testu i oczekiwany produkt. Przy odbiorze rozróżnij badanie laboratoryjne od oceny wizualnej.","Sprawdź zasadę. Partia A ma 11% białka, partia B 13%. Sam procent białka nie wystarcza do uznania B za lepszą do każdego chleba: potrzebne są cechy funkcjonalne, warunki testu i oczekiwany produkt. Przy odbiorze rozróżnij badanie laboratoryjne od oceny wizualnej."],"question":"Dlaczego nie można określić przydatności każdej mąki wyłącznie po procentowej zawartości białka?","situation":"Porównujesz dwie mąki do konkretnego wypieku. Na kartach produktu znajdziesz zawartość białka, ale brakuje opisu zachowania ciasta.","explanation":"Partia A ma 11% białka, partia B 13%. Sam procent białka nie wystarcza do uznania B za lepszą do każdego chleba: potrzebne są cechy funkcjonalne, warunki testu i oczekiwany produkt. Przy odbiorze rozróżnij badanie laboratoryjne od oceny wizualnej."}}$data$::jsonb),
 ('mlynarz-tradycyjny',10,$data${"learning":{"task":"Zrób drzewo diagnostyczne dla trzech objawów: pylenie, spadek wydajności i podejrzany pył kamienny. W każdej gałęzi uwzględnij bezpieczeństwo, dane kontrolne i możliwość zatrzymania procesu.","correct":2,"example":"20%.","options":["10%.","15%.","20%.","25%."],"feedback":["Sprawdź zasadę. Zakład deklaruje 200 kg przemiału w 4 godziny, czyli 50 kg/h. Jeśli ten sam proces zajął 5 godzin, wydajność to 40 kg/h, spadek o 20% względem poprzedniej wartości. Trzeba zbadać przyczyny zamiast przyspieszać napęd na ślepo.","Sprawdź zasadę. Zakład deklaruje 200 kg przemiału w 4 godziny, czyli 50 kg/h. Jeśli ten sam proces zajął 5 godzin, wydajność to 40 kg/h, spadek o 20% względem poprzedniej wartości. Trzeba zbadać przyczyny zamiast przyspieszać napęd na ślepo.","Dobrze. Zakład deklaruje 200 kg przemiału w 4 godziny, czyli 50 kg/h. Jeśli ten sam proces zajął 5 godzin, wydajność to 40 kg/h, spadek o 20% względem poprzedniej wartości. Trzeba zbadać przyczyny zamiast przyspieszać napęd na ślepo.","Sprawdź zasadę. Zakład deklaruje 200 kg przemiału w 4 godziny, czyli 50 kg/h. Jeśli ten sam proces zajął 5 godzin, wydajność to 40 kg/h, spadek o 20% względem poprzedniej wartości. Trzeba zbadać przyczyny zamiast przyspieszać napęd na ślepo."],"question":"Przemiał 200 kg trwał 4 godziny, a następnie 5 godzin. O ile procent zmalała wydajność godzinowa?","situation":"Ostatnie dwa zapisy z produkcji dotyczą tej samej masy ziarna. Czas wzrósł z czterech do pięciu godzin. Oblicz, o ile spadła wydajność godzinowa.","explanation":"Zakład deklaruje 200 kg przemiału w 4 godziny, czyli 50 kg/h. Jeśli ten sam proces zajął 5 godzin, wydajność to 40 kg/h, spadek o 20% względem poprzedniej wartości. Trzeba zbadać przyczyny zamiast przyspieszać napęd na ślepo."}}$data$::jsonb),
 ('mlynarz-tradycyjny',11,$data${"learning":{"task":"Przygotuj schemat przepływu, bilans masowy, plan urządzeń, 10-punktową kartę jakości i 10-punktową SJA. Uzasadnij różnicę między wydajnością wsadu a wydajnością mąki i zaznacz ryzyko zapłonu pyłu.","correct":2,"example":"75%.","options":["65%.","70%.","75%.","85%."],"feedback":["Sprawdź zasadę. Model: przyjęto 500 kg ziarna, usunięto 10 kg obcych zanieczyszczeń — pozostaje 490 kg. Uzyskano 367,5 kg mąki, czyli 367,5/490=75% wyciągu. Pozostałe frakcje i straty muszą sumować się do 122,5 kg. Przy czterech godzinach przemiału wydajność mąki to 91,875 kg/h, nie 125 kg/h (ta druga wartość odnosiłaby się do całego surowca przed przemiałem).","Sprawdź zasadę. Model: przyjęto 500 kg ziarna, usunięto 10 kg obcych zanieczyszczeń — pozostaje 490 kg. Uzyskano 367,5 kg mąki, czyli 367,5/490=75% wyciągu. Pozostałe frakcje i straty muszą sumować się do 122,5 kg. Przy czterech godzinach przemiału wydajność mąki to 91,875 kg/h, nie 125 kg/h (ta druga wartość odnosiłaby się do całego surowca przed przemiałem).","Dobrze. Model: przyjęto 500 kg ziarna, usunięto 10 kg obcych zanieczyszczeń — pozostaje 490 kg. Uzyskano 367,5 kg mąki, czyli 367,5/490=75% wyciągu. Pozostałe frakcje i straty muszą sumować się do 122,5 kg. Przy czterech godzinach przemiału wydajność mąki to 91,875 kg/h, nie 125 kg/h (ta druga wartość odnosiłaby się do całego surowca przed przemiałem).","Sprawdź zasadę. Model: przyjęto 500 kg ziarna, usunięto 10 kg obcych zanieczyszczeń — pozostaje 490 kg. Uzyskano 367,5 kg mąki, czyli 367,5/490=75% wyciągu. Pozostałe frakcje i straty muszą sumować się do 122,5 kg. Przy czterech godzinach przemiału wydajność mąki to 91,875 kg/h, nie 125 kg/h (ta druga wartość odnosiłaby się do całego surowca przed przemiałem)."],"question":"Z 490 kg oczyszczonego ziarna otrzymano 367,5 kg mąki. Jaki jest wyciąg?","situation":"Po czyszczeniu 500 kg dostawy zostało 490 kg ziarna. Z tej partii odebrano 367,5 kg mąki. Ustal wyciąg i wskaż masę, którą przyjmujesz za podstawę.","explanation":"Model: przyjęto 500 kg ziarna, usunięto 10 kg obcych zanieczyszczeń — pozostaje 490 kg. Uzyskano 367,5 kg mąki, czyli 367,5/490=75% wyciągu. Pozostałe frakcje i straty muszą sumować się do 122,5 kg. Przy czterech godzinach przemiału wydajność mąki to 91,875 kg/h, nie 125 kg/h (ta druga wartość odnosiłaby się do całego surowca przed przemiałem)."}}$data$::jsonb),
 ('powroznik',7,$data${"learning":{"task":"Sporządź tabelę pięciu typów wad ze źródłem, objawem, możliwą niewidoczną szkodą, kryterium wycofania i wymaganym dokumentem. Policz 20% wadliwych sztuk z podanego przykładu.","intro":"Przecięte włókna, miejscowe ścieranie, kinki i hockles, zgniecenie, uszkodzenia chemiczne, starzenie oraz nadmierne wydłużenie to różne kategorie wad. Zewnętrzny wygląd nie zawsze ujawnia całą utratę wytrzymałości. Procedura wycofania zależy od konstrukcji i zastosowania oraz dokumentów producenta.","correct":1,"example":"5 lin","options":["6 lin","5 lin","4 liny","3 liny"],"feedback":["Sprawdź obliczenie. Dodaj 4 i 2, a potem odejmij 1 wspólną sztukę. Wynik to 5 unikatowych lin.","Dobrze. Dodaj 4 i 2, a potem odejmij 1 wspólną sztukę. Wynik to 5 unikatowych lin.","Sprawdź obliczenie. Dodaj 4 i 2, a potem odejmij 1 wspólną sztukę. Wynik to 5 unikatowych lin.","Sprawdź obliczenie. Dodaj 4 i 2, a potem odejmij 1 wspólną sztukę. Wynik to 5 unikatowych lin."],"question":"W 25 linach są cztery z wadą A i dwie z B, ale jedna ma obie. Ile unikatowych lin ma wadę?","situation":"W rejestrze 25 lin cztery sztuki mają wadę A, dwie wadę B, a jedna sztuka znajduje się na obu listach.","explanation":"Dodaj 4 i 2, a potem odejmij 1 wspólną sztukę. Wynik to 5 unikatowych lin."}}$data$::jsonb),
 ('powroznik',10,$data${"learning":{"task":"Zbuduj rejestr 40 lin z numerem, materiałem, długością, stanem, warunkami przechowania, historią, datą kontroli i decyzją. Policz udział siedmiu niezgodnych sztuk.","intro":"Liny naturalne i syntetyczne wymagają różnych warunków magazynowania. Należy chronić je przed nieodpowiednią wilgotnością, wysoką temperaturą, promieniowaniem UV i zanieczyszczeniami niezgodnymi z materiałem. Nadmierne skręty, ostre krawędzie i przeciąganie po szorstkich powierzchniach przyspieszają zużycie.","correct":1,"example":"7 lin","options":["9 lin","7 lin","5 lin","11 lin"],"feedback":["Sprawdź obliczenie. Suma 5 + 4 liczy dwie sztuki podwójnie. Po odjęciu 2 pozostaje 7 lin z wadą.","Dobrze. Suma 5 + 4 liczy dwie sztuki podwójnie. Po odjęciu 2 pozostaje 7 lin z wadą.","Sprawdź obliczenie. Suma 5 + 4 liczy dwie sztuki podwójnie. Po odjęciu 2 pozostaje 7 lin z wadą.","Sprawdź obliczenie. Suma 5 + 4 liczy dwie sztuki podwójnie. Po odjęciu 2 pozostaje 7 lin z wadą."],"question":"W 40 linach 5 ma wadę mechaniczną, 4 chemiczną, a 2 obie. Ile unikalnych sztuk ma widoczną wadę?","situation":"W magazynie sprawdzasz 40 lin. Pięć wykazuje wadę mechaniczną, cztery wadę chemiczną, a dwie mają obie wady.","explanation":"Suma 5 + 4 liczy dwie sztuki podwójnie. Po odjęciu 2 pozostaje 7 lin z wadą."}}$data$::jsonb),
 ('jestem-eko',0,$data${"learning":{"task":"Powiedz Anielce, jak zastosujesz tę zasadę u siebie: Zastanawiam się, czy zmiana rzeczywiście zmniejszy zużycie zasobów, i zachowuję sprawny sprzęt.","intro":"Bycie eko nie polega na idealności ani na kupowaniu gadżetów z zieloną etykietą. Zaczyna się od pytania: czy naprawdę potrzebuję nowej rzeczy? Unikanie niepotrzebnego zakupu i przedłużanie życia przedmiotów zwykle mają sens przed ich segregacją.","correct":0,"example":"Zastanawiam się, czy zmiana rzeczywiście zmniejszy zużycie zasobów, i zachowuję sprawny sprzęt.","options":["Zastanawiam się, czy zmiana rzeczywiście zmniejszy zużycie zasobów, i zachowuję sprawny sprzęt.","Kupuję drugi tylko dlatego, że ma zielony kolor.","Kupię nowy, jeśli deklaruje mniejsze zużycie przy pojedynczym gotowaniu, i od razu wycofam działający."],"feedback":["Tak — Zastanawiam się, czy zmiana rzeczywiście zmniejszy zużycie zasobów, i zachowuję sprawny sprzęt.","To nie jest właściwe. Bycie eko nie polega na idealności ani na kupowaniu gadżetów z zieloną etykietą. Zaczyna się od pytania: czy naprawdę potrzebuję nowej rzeczy? Unikanie niepotrzebnego zakupu i przedłużanie życia przedmiotów zwykle mają sens przed ich segregacją.","Jedno porównanie zużycia nie obejmuje produkcji nowego urządzenia ani tego, jak często używasz czajnika."],"question":"Co sprawdzisz przed wymianą sprawnego czajnika?","situation":"Masz sprawny czajnik, ale reklama poleca nowy ekologiczny model.","explanation":"Bycie eko nie polega na idealności ani na kupowaniu gadżetów z zieloną etykietą. Zaczyna się od pytania: czy naprawdę potrzebuję nowej rzeczy? Unikanie niepotrzebnego zakupu i przedłużanie życia przedmiotów zwykle mają sens przed ich segregacją."}}$data$::jsonb),
 ('jestem-eko',1,$data${"learning":{"task":"Powiedz Anielce, jak zastosujesz tę zasadę u siebie: Najpierw oceniam, czy istniejąca odzież wystarczy i jak długo użyję nowej.","intro":"Produkt przechodzi etapy: surowce, produkcja, transport, używanie, naprawa i koniec życia. Koszulka, telefon i szklana butelka obciążają środowisko w różnych momentach. Sam kolor kosza nie mówi nic o energii potrzebnej do ich produkcji.","correct":1,"example":"Najpierw oceniam, czy istniejąca odzież wystarczy i jak długo użyję nowej.","options":["Porównam tylko odległość transportu obu koszulek, bo pozostałe etapy mają podobne znaczenie.","Najpierw oceniam, czy istniejąca odzież wystarczy i jak długo użyję nowej.","Wyrzucam pięć sprawnych koszulek, aby zrobić miejsce."],"feedback":["Trwałość, produkcja, sposób używania i liczba założeń też wpływają na wynik.","Tak — Najpierw oceniam, czy istniejąca odzież wystarczy i jak długo użyję nowej.","To nie jest właściwe. Produkt przechodzi etapy: surowce, produkcja, transport, używanie, naprawa i koniec życia. Koszulka, telefon i szklana butelka obciążają środowisko w różnych momentach. Sam kolor kosza nie mówi nic o energii potrzebnej do ich produkcji."],"question":"Co pomoże ocenić sens zakupu koszulki?","situation":"Kupujesz kolejną koszulkę, choć w szafie masz dwadzieścia.","explanation":"Produkt przechodzi etapy: surowce, produkcja, transport, używanie, naprawa i koniec życia. Koszulka, telefon i szklana butelka obciążają środowisko w różnych momentach. Sam kolor kosza nie mówi nic o energii potrzebnej do ich produkcji."}}$data$::jsonb),
 ('jestem-eko',2,$data${"learning":{"task":"Powiedz Anielce, jak zastosujesz tę zasadę u siebie: Sprawdzam naprawę zamka i dalsze używanie.","intro":"Europejska hierarchia stawia przed recyklingiem zapobieganie powstawaniu odpadów oraz przygotowanie do ponownego użycia. Potem jest recykling, inny odzysk i dopiero unieszkodliwianie. Samo przekazanie rzeczy do recyklingu nie zawsze jest najlepszym wyborem.","correct":2,"example":"Sprawdzam naprawę zamka i dalsze używanie.","options":["Wrzucam cały plecak do plastiku, bo ma plastikowy zamek.","Od razu oddam cały plecak do zbiórki tekstyliów, bo zamek przestał działać.","Sprawdzam naprawę zamka i dalsze używanie."],"feedback":["To nie jest właściwe. Europejska hierarchia stawia przed recyklingiem zapobieganie powstawaniu odpadów oraz przygotowanie do ponownego użycia. Potem jest recykling, inny odzysk i dopiero unieszkodliwianie. Samo przekazanie rzeczy do recyklingu nie zawsze jest najlepszym wyborem.","Sprawna tkanina jest przesłanką do oceny, czy naprawa zamka pozwoli używać plecaka dalej.","Tak — Sprawdzam naprawę zamka i dalsze używanie."],"question":"Jaki krok pozwoli zachować plecak w użyciu?","situation":"W plecaku zepsuł się zamek, ale materiał nadal jest mocny.","explanation":"Europejska hierarchia stawia przed recyklingiem zapobieganie powstawaniu odpadów oraz przygotowanie do ponownego użycia. Potem jest recykling, inny odzysk i dopiero unieszkodliwianie. Samo przekazanie rzeczy do recyklingu nie zawsze jest najlepszym wyborem."}}$data$::jsonb),
 ('jestem-eko',3,$data${"learning":{"task":"Powiedz Anielce, jak zastosujesz tę zasadę u siebie: Postępuję według zasad lokalnej zbiórki i zgłaszam niebezpieczną zawartość.","intro":"Odpady kierowane są do sortowania i przetwarzania, a część do odzysku energii lub unieszkodliwienia. Zabrudzony papier czy bateria wrzucona do odpadów zmieszanych mogą pogorszyć bezpieczeństwo i jakość odbioru. Trójkąt na opakowaniu nie daje gwarancji, że ten przedmiot zostanie lokalnie przetworzony.","correct":0,"example":"Postępuję według zasad lokalnej zbiórki i zgłaszam niebezpieczną zawartość.","options":["Postępuję według zasad lokalnej zbiórki i zgłaszam niebezpieczną zawartość.","Zakładam, że sortownia zawsze naprawi każdy błąd i nic nie robię.","Zajmę się tylko tłustym opakowaniem i zostawię baterię do sortowania razem z papierem."],"feedback":["Tak — Postępuję według zasad lokalnej zbiórki i zgłaszam niebezpieczną zawartość.","To nie jest właściwe. Odpady kierowane są do sortowania i przetwarzania, a część do odzysku energii lub unieszkodliwienia. Zabrudzony papier czy bateria wrzucona do odpadów zmieszanych mogą pogorszyć bezpieczeństwo i jakość odbioru. Trójkąt na opakowaniu nie daje gwarancji, że ten przedmiot zostanie lokalnie przetworzony.","Bateria wymaga odrębnego postępowania. Operator powinien wiedzieć o możliwej niebezpiecznej zawartości."],"question":"Jak zareagujesz na baterię w pojemniku z papierem?","situation":"W pojemniku z papierem widzisz baterię i tłuste opakowanie.","explanation":"Odpady kierowane są do sortowania i przetwarzania, a część do odzysku energii lub unieszkodliwienia. Zabrudzony papier czy bateria wrzucona do odpadów zmieszanych mogą pogorszyć bezpieczeństwo i jakość odbioru. Trójkąt na opakowaniu nie daje gwarancji, że ten przedmiot zostanie lokalnie przetworzony."}}$data$::jsonb),
 ('jestem-eko',4,$data${"learning":{"task":"Powiedz Anielce, jak zastosujesz tę zasadę u siebie: Rozdzielam papier, plastikowe opakowanie i szkło do właściwych frakcji.","intro":"W Jednolitym Systemie Segregacji Odpadów kolor niebieski oznacza papier, żółty metale i tworzywa sztuczne, zielony szkło opakowaniowe, brązowy bio, a pozostałe resztkowe zbierane są osobno. Baterie, leki i elektronika to wyjątki, które wymagają własnej ścieżki.","correct":1,"example":"Rozdzielam papier, plastikowe opakowanie i szkło do właściwych frakcji.","options":["Gazetę i butelkę wrzucę razem, bo oba surowce nadają się do dalszego przetworzenia.","Rozdzielam papier, plastikowe opakowanie i szkło do właściwych frakcji.","Wrzucam wszystko do jednego kosza, bo wszystkie są opakowaniami."],"feedback":["To, że dwa materiały można przetworzyć, nie oznacza wspólnego pojemnika. Przy butelce najpierw odczytaj znak kaucji.","Tak — Rozdzielam papier, plastikowe opakowanie i szkło do właściwych frakcji.","To nie jest właściwe. W Jednolitym Systemie Segregacji Odpadów kolor niebieski oznacza papier, żółty metale i tworzywa sztuczne, zielony szkło opakowaniowe, brązowy bio, a pozostałe resztkowe zbierane są osobno. Baterie, leki i elektronika to wyjątki, które wymagają własnej ścieżki."],"question":"Jak rozdzielisz odpady opakowaniowe i gazetę?","situation":"Masz gazetę, pustą butelkę PET i słoik po dżemie.","explanation":"W Jednolitym Systemie Segregacji Odpadów kolor niebieski oznacza papier, żółty metale i tworzywa sztuczne, zielony szkło opakowaniowe, brązowy bio, a pozostałe resztkowe zbierane są osobno. Baterie, leki i elektronika to wyjątki, które wymagają własnej ścieżki."}}$data$::jsonb),
 ('jestem-eko',5,$data${"learning":{"task":"Powiedz Anielce, jak zastosujesz tę zasadę u siebie: Sprawdzam aktualną instrukcję segregacji dla adresu, zamiast kopiować stare nawyki.","intro":"W Norwegii często spotkasz nazwy matavfall, papp/papir, plastemballasje, glass- og metallemballasje oraz restavfall. Kolory worków i sposób odbioru mogą różnić się między gminami. Właściwe instrukcje sprawdzisz u lokalnego operatora lub na sortere.no.","correct":2,"example":"Sprawdzam aktualną instrukcję segregacji dla adresu, zamiast kopiować stare nawyki.","options":["Zakładam, że każda gmina ma identyczne zasady.","Użyję kolorów z sąsiedniej gminy, bo oba miejsca obsługuje podobny samochód odbioru.","Sprawdzam aktualną instrukcję segregacji dla adresu, zamiast kopiować stare nawyki."],"feedback":["To nie jest właściwe. W Norwegii często spotkasz nazwy matavfall, papp/papir, plastemballasje, glass- og metallemballasje oraz restavfall. Kolory worków i sposób odbioru mogą różnić się między gminami. Właściwe instrukcje sprawdzisz u lokalnego operatora lub na sortere.no.","Wiążąca dla tego ćwiczenia jest instrukcja przypisana do nowego adresu i rodzaju odpadów.","Tak — Sprawdzam aktualną instrukcję segregacji dla adresu, zamiast kopiować stare nawyki."],"question":"Która informacja decyduje o właściwym worku po przeprowadzce?","situation":"Przenosisz się z Oslo do innej gminy i zauważasz inne kolory worków.","explanation":"W Norwegii często spotkasz nazwy matavfall, papp/papir, plastemballasje, glass- og metallemballasje oraz restavfall. Kolory worków i sposób odbioru mogą różnić się między gminami. Właściwe instrukcje sprawdzisz u lokalnego operatora lub na sortere.no."}}$data$::jsonb),
 ('jestem-eko',6,$data${"learning":{"task":"Powiedz Anielce, jak zastosujesz tę zasadę u siebie: Spłaszczam je i umieszczam w odpowiedniej frakcji papieru.","intro":"Czysty papier, gazety i tektura zwykle trafiają do osobnej frakcji. Tłuszcz i resztki jedzenia mogą utrudnić odzysk włókien. Nie każdy karton po mleku ma identyczną drogę w różnych systemach zbiórki; lokalne instrukcje są ważniejsze od samej nazwy materiału.","correct":0,"example":"Spłaszczam je i umieszczam w odpowiedniej frakcji papieru.","options":["Spłaszczam je i umieszczam w odpowiedniej frakcji papieru.","Wrzucam do niego baterie i opakowania plastikowe, bo to też śmieci.","Zostawię pudełko rozłożone przestrzennie, bo sprasowanie zmienia rodzaj papieru."],"feedback":["Tak — Spłaszczam je i umieszczam w odpowiedniej frakcji papieru.","To nie jest właściwe. Czysty papier, gazety i tektura zwykle trafiają do osobnej frakcji. Tłuszcz i resztki jedzenia mogą utrudnić odzysk włókien. Nie każdy karton po mleku ma identyczną drogę w różnych systemach zbiórki; lokalne instrukcje są ważniejsze od samej nazwy materiału.","Złożenie pudełka oszczędza miejsce. Czysty karton nadal należy do frakcji papieru."],"question":"Co zrobisz z czystym kartonem po dostawie?","situation":"Składasz czyste pudło kartonowe po przesyłce.","explanation":"Czysty papier, gazety i tektura zwykle trafiają do osobnej frakcji. Tłuszcz i resztki jedzenia mogą utrudnić odzysk włókien. Nie każdy karton po mleku ma identyczną drogę w różnych systemach zbiórki; lokalne instrukcje są ważniejsze od samej nazwy materiału."}}$data$::jsonb),
 ('jestem-eko',7,$data${"learning":{"task":"Powiedz Anielce, jak zastosujesz tę zasadę u siebie: Butelkę klasyfikuję jako opakowanie, a szczoteczkę sprawdzam jako przedmiot nieopakowaniowy.","intro":"Do frakcji opakowań z tworzyw może trafić pusta butelka po szamponie, ale zużyta szczoteczka do zębów albo plastikowa zabawka nie jest opakowaniem. Symbol rodzaju tworzywa opisuje materiał, nie zapewnia lokalnego odbioru. Opakowanie powinno być opróżnione zgodnie z lokalnymi wytycznymi.","correct":1,"example":"Butelkę klasyfikuję jako opakowanie, a szczoteczkę sprawdzam jako przedmiot nieopakowaniowy.","options":["Wrzucę szczoteczkę do tej samej frakcji co butelkę, kierując się wyłącznie tworzywem.","Butelkę klasyfikuję jako opakowanie, a szczoteczkę sprawdzam jako przedmiot nieopakowaniowy.","Obie wrzucam do opakowań z plastiku tylko dlatego, że są z plastiku."],"feedback":["Instrukcja może inaczej traktować opakowania i przedmioty nieopakowaniowe. Sprawdź odbiór szczoteczki lokalnie.","Tak — Butelkę klasyfikuję jako opakowanie, a szczoteczkę sprawdzam jako przedmiot nieopakowaniowy.","To nie jest właściwe. Do frakcji opakowań z tworzyw może trafić pusta butelka po szamponie, ale zużyta szczoteczka do zębów albo plastikowa zabawka nie jest opakowaniem. Symbol rodzaju tworzywa opisuje materiał, nie zapewnia lokalnego odbioru. Opakowanie powinno być opróżnione zgodnie z lokalnymi wytycznymi."],"question":"Jak odróżnisz zasady dla tych dwóch plastikowych rzeczy?","situation":"Masz pustą butelkę po szamponie i złamaną szczoteczkę.","explanation":"Do frakcji opakowań z tworzyw może trafić pusta butelka po szamponie, ale zużyta szczoteczka do zębów albo plastikowa zabawka nie jest opakowaniem. Symbol rodzaju tworzywa opisuje materiał, nie zapewnia lokalnego odbioru. Opakowanie powinno być opróżnione zgodnie z lokalnymi wytycznymi."}}$data$::jsonb),
 ('jestem-eko',8,$data${"learning":{"task":"Powiedz Anielce, jak zastosujesz tę zasadę u siebie: Słoik oddaję do szkła opakowaniowego, kubek do właściwej lokalnej frakcji, nie mieszam ich.","intro":"Do pojemników na szkło opakowaniowe nie należy automatycznie wrzucać ceramiki, luster, szyb, szkła żaroodpornego ani żarówek. Różne składy i sposoby przetwarzania mają znaczenie. Szczegóły odbioru odłamków i materiałów budowlanych sprawdź lokalnie.","correct":2,"example":"Słoik oddaję do szkła opakowaniowego, kubek do właściwej lokalnej frakcji, nie mieszam ich.","options":["Wrzucam oba do zielonego pojemnika na szkło.","Wrzucę słoik razem z kubkiem, jeśli oba przedmioty mają podobny kolor.","Słoik oddaję do szkła opakowaniowego, kubek do właściwej lokalnej frakcji, nie mieszam ich."],"feedback":["To nie jest właściwe. Do pojemników na szkło opakowaniowe nie należy automatycznie wrzucać ceramiki, luster, szyb, szkła żaroodpornego ani żarówek. Różne składy i sposoby przetwarzania mają znaczenie. Szczegóły odbioru odłamków i materiałów budowlanych sprawdź lokalnie.","Kolor nie zmienia tego, że kubek jest ceramiczny, a słoik jest szklanym opakowaniem.","Tak — Słoik oddaję do szkła opakowaniowego, kubek do właściwej lokalnej frakcji, nie mieszam ich."],"question":"Który przedmiot pasuje do typowej zbiórki szkła opakowaniowego?","situation":"W kuchni pękł ceramiczny kubek, a obok stoi pusty szklany słoik.","explanation":"Do pojemników na szkło opakowaniowe nie należy automatycznie wrzucać ceramiki, luster, szyb, szkła żaroodpornego ani żarówek. Różne składy i sposoby przetwarzania mają znaczenie. Szczegóły odbioru odłamków i materiałów budowlanych sprawdź lokalnie."}}$data$::jsonb),
 ('jestem-eko',9,$data${"learning":{"task":"Powiedz Anielce, jak zastosujesz tę zasadę u siebie: Obierki segreguję lokalnie jako bio, a olej oddaję odpowiednio, nie wylewam go do kanalizacji.","intro":"Obierki i pozostałości żywności często trafiają do bio lub matavfall, ale zasady dla kości, tłuszczu, dużych gałęzi i worków zależą od systemu. Oleju po smażeniu nie wlewaj do zlewu. BIO nie znaczy, że każda naturalna rzecz pasuje do worka.","correct":0,"example":"Obierki segreguję lokalnie jako bio, a olej oddaję odpowiednio, nie wylewam go do kanalizacji.","options":["Obierki segreguję lokalnie jako bio, a olej oddaję odpowiednio, nie wylewam go do kanalizacji.","Wylewam cały olej do odpływu, bo pochodzi z jedzenia.","Wleję olej do worka BIO razem z obierkami, skoro oba pochodzą z gotowania."],"feedback":["Tak — Obierki segreguję lokalnie jako bio, a olej oddaję odpowiednio, nie wylewam go do kanalizacji.","To nie jest właściwe. Obierki i pozostałości żywności często trafiają do bio lub matavfall, ale zasady dla kości, tłuszczu, dużych gałęzi i worków zależą od systemu. Oleju po smażeniu nie wlewaj do zlewu. BIO nie znaczy, że każda naturalna rzecz pasuje do worka.","Odpady kuchenne i płynny tłuszcz mogą wymagać innych dróg odbioru. Sprawdź lokalną instrukcję."],"question":"Jak osobno potraktujesz obierki i olej?","situation":"Pozostał olej z patelni i obierki z ziemniaków.","explanation":"Obierki i pozostałości żywności często trafiają do bio lub matavfall, ale zasady dla kości, tłuszczu, dużych gałęzi i worków zależą od systemu. Oleju po smażeniu nie wlewaj do zlewu. BIO nie znaczy, że każda naturalna rzecz pasuje do worka."}}$data$::jsonb),
 ('jestem-eko',10,$data${"learning":{"task":"Powiedz Anielce, jak zastosujesz tę zasadę u siebie: Izoluję zagrożenie zgodnie z zasadami bezpieczeństwa i pytam punkt specjalny o odbiór; z telefonu usuwam dane.","intro":"Baterie i akumulatory mogą powodować pożary w strumieniu odpadów. Telefony, ładowarki, komputery i LED-y wymagają odpowiednich punktów zbiórki. Przed oddaniem urządzenia warto wykonać kopię danych i usunąć konta. Nie rozbieraj uszkodzonych akumulatorów samodzielnie.","correct":1,"example":"Izoluję zagrożenie zgodnie z zasadami bezpieczeństwa i pytam punkt specjalny o odbiór; z telefonu usuwam dane.","options":["Rozładuję spuchniętą baterię do zera, żeby łatwiej ją potem przewieźć.","Izoluję zagrożenie zgodnie z zasadami bezpieczeństwa i pytam punkt specjalny o odbiór; z telefonu usuwam dane.","Przebijam baterię, aby zmniejszyć jej rozmiar."],"feedback":["Dalsze używanie uszkodzonego ogniwa zwiększa ryzyko. Ustal bezpieczne postępowanie z punktem, który odbiera takie odpady.","Tak — Izoluję zagrożenie zgodnie z zasadami bezpieczeństwa i pytam punkt specjalny o odbiór; z telefonu usuwam dane.","To nie jest właściwe. Baterie i akumulatory mogą powodować pożary w strumieniu odpadów. Telefony, ładowarki, komputery i LED-y wymagają odpowiednich punktów zbiórki. Przed oddaniem urządzenia warto wykonać kopię danych i usunąć konta. Nie rozbieraj uszkodzonych akumulatorów samodzielnie."],"question":"Co jest pierwszym krokiem, gdy zauważysz spuchniętą baterię?","situation":"W szufladzie leży spuchnięta bateria i stary telefon.","explanation":"Baterie i akumulatory mogą powodować pożary w strumieniu odpadów. Telefony, ładowarki, komputery i LED-y wymagają odpowiednich punktów zbiórki. Przed oddaniem urządzenia warto wykonać kopię danych i usunąć konta. Nie rozbieraj uszkodzonych akumulatorów samodzielnie."}}$data$::jsonb),
 ('jestem-eko',11,$data${"learning":{"task":"Powiedz Anielce, jak zastosujesz tę zasadę u siebie: Przechowuję szczelnie i oddaję zgodnie z zasadami odbioru odpadów niebezpiecznych.","intro":"Odpady niebezpieczne, takie jak resztki rozpuszczalników, farb, chemikaliów i leków, nie należą do bio. Nie wylewaj ich do kanalizacji; sprawdź specjalne punkty zbiórki i oznacz pojemniki. Część aptek odbiera określone leki w ramach lokalnych systemów.","correct":2,"example":"Przechowuję szczelnie i oddaję zgodnie z zasadami odbioru odpadów niebezpiecznych.","options":["Wylewam oba płyny do toalety.","Zleję pozostałości farby i rozpuszczalnika do jednego pojemnika, żeby ograniczyć liczbę opakowań.","Przechowuję szczelnie i oddaję zgodnie z zasadami odbioru odpadów niebezpiecznych."],"feedback":["To nie jest właściwe. Odpady niebezpieczne, takie jak resztki rozpuszczalników, farb, chemikaliów i leków, nie należą do bio. Nie wylewaj ich do kanalizacji; sprawdź specjalne punkty zbiórki i oznacz pojemniki. Część aptek odbiera określone leki w ramach lokalnych systemów.","Łączenie substancji może stworzyć nowe zagrożenie i utrudnia identyfikację. Przekaż odpady według zasad danego punktu.","Tak — Przechowuję szczelnie i oddaję zgodnie z zasadami odbioru odpadów niebezpiecznych."],"question":"Jak przygotujesz się do oddania pozostałości po remoncie?","situation":"Po remoncie została puszka z resztką farby i opakowanie po rozpuszczalniku.","explanation":"Odpady niebezpieczne, takie jak resztki rozpuszczalników, farb, chemikaliów i leków, nie należą do bio. Nie wylewaj ich do kanalizacji; sprawdź specjalne punkty zbiórki i oznacz pojemniki. Część aptek odbiera określone leki w ramach lokalnych systemów."}}$data$::jsonb),
 ('jestem-eko',12,$data${"learning":{"task":"Powiedz Anielce, jak zastosujesz tę zasadę u siebie: Sprawdzam naprawę zamka, zanim uznam kurtkę za odpad.","intro":"Ubranie w dobrym stanie lepiej naprawić albo przekazać do ponownego noszenia. Uszkodzone tekstylia oddaj do wskazanej zbiórki, a nie do mieszanych. W Polsce od 2025 r. gminy zapewniają selektywną zbiórkę tekstyliów m.in. przez PSZOK; sprawdzaj warunki przyjęcia.","correct":0,"example":"Sprawdzam naprawę zamka, zanim uznam kurtkę za odpad.","options":["Sprawdzam naprawę zamka, zanim uznam kurtkę za odpad.","Wyrzucam kurtkę do plastiku, bo ma plastikowy zamek.","Kupuję nową i oddaję starą jako zużytą, zanim zapytam o możliwość wymiany zamka."],"feedback":["Tak — Sprawdzam naprawę zamka, zanim uznam kurtkę za odpad.","To nie jest właściwe. Ubranie w dobrym stanie lepiej naprawić albo przekazać do ponownego noszenia. Uszkodzone tekstylia oddaj do wskazanej zbiórki, a nie do mieszanych. W Polsce od 2025 r. gminy zapewniają selektywną zbiórkę tekstyliów m.in. przez PSZOK; sprawdzaj warunki przyjęcia.","Wymiana jednego elementu może przywrócić funkcję całej kurtki. Oceń stan materiału i koszt naprawy."],"question":"Jak zdecydujesz, czy kurtka jest już odpadem?","situation":"W kurtce pękł zamek, ale materiał jest dobry.","explanation":"Ubranie w dobrym stanie lepiej naprawić albo przekazać do ponownego noszenia. Uszkodzone tekstylia oddaj do wskazanej zbiórki, a nie do mieszanych. W Polsce od 2025 r. gminy zapewniają selektywną zbiórkę tekstyliów m.in. przez PSZOK; sprawdzaj warunki przyjęcia."}}$data$::jsonb),
 ('jestem-eko',13,$data${"learning":{"task":"Powiedz Anielce, jak zastosujesz tę zasadę u siebie: Sprawdzam skład, trwałość, źródło deklaracji i czy zakup jest potrzebny.","intro":"Określenia naturalny, zielony czy zrównoważony nie mówią same w sobie o pełnym wpływie produktu. Porównuj trwałość, rzeczywistą potrzebę zakupu, sposób pielęgnacji i zakres wiarygodnych certyfikatów. Dłuższe użytkowanie jest ważne; sam materiał nie daje uniwersalnego rankingu.","correct":1,"example":"Sprawdzam skład, trwałość, źródło deklaracji i czy zakup jest potrzebny.","options":["Uznam wyższą cenę za dowód lepszego wpływu na środowisko.","Sprawdzam skład, trwałość, źródło deklaracji i czy zakup jest potrzebny.","Kupuję natychmiast, bo metka ma zielony liść."],"feedback":["Cena sama w sobie nie potwierdza deklaracji. Weryfikuj zakres, dane i planowany czas używania.","Tak — Sprawdzam skład, trwałość, źródło deklaracji i czy zakup jest potrzebny.","To nie jest właściwe. Określenia naturalny, zielony czy zrównoważony nie mówią same w sobie o pełnym wpływie produktu. Porównuj trwałość, rzeczywistą potrzebę zakupu, sposób pielęgnacji i zakres wiarygodnych certyfikatów. Dłuższe użytkowanie jest ważne; sam materiał nie daje uniwersalnego rankingu."],"question":"Jak sprawdzisz, co naprawdę znaczy „eko” na etykiecie?","situation":"Sklep nazywa nową koszulkę „eko”, lecz nie podaje szczegółów.","explanation":"Określenia naturalny, zielony czy zrównoważony nie mówią same w sobie o pełnym wpływie produktu. Porównuj trwałość, rzeczywistą potrzebę zakupu, sposób pielęgnacji i zakres wiarygodnych certyfikatów. Dłuższe użytkowanie jest ważne; sam materiał nie daje uniwersalnego rankingu."}}$data$::jsonb),
 ('jestem-eko',14,$data${"learning":{"task":"Powiedz Anielce, jak zastosujesz tę zasadę u siebie: Nie używam mięsa po tej dacie, nawet jeśli wygląda poprawnie.","intro":"Plan zakupów i ustawienie produktów w lodówce pomagają ograniczać wyrzucanie żywności. „Najlepiej spożyć przed” opisuje jakość, a „należy spożyć do” odnosi się do bezpieczeństwa. Produktu po terminie „należy spożyć do” nie spożywaj; nie oceniaj ryzyka wyłącznie zapachem.","correct":2,"example":"Nie używam mięsa po tej dacie, nawet jeśli wygląda poprawnie.","options":["Gotuję je mocniej, aby odzyskać bezpieczeństwo.","Ocenię zapach mięsa i wykorzystam je, jeśli nic nie budzi podejrzeń.","Nie używam mięsa po tej dacie, nawet jeśli wygląda poprawnie."],"feedback":["To nie jest właściwe. Plan zakupów i ustawienie produktów w lodówce pomagają ograniczać wyrzucanie żywności. „Najlepiej spożyć przed” opisuje jakość, a „należy spożyć do” odnosi się do bezpieczeństwa. Produktu po terminie „należy spożyć do” nie spożywaj; nie oceniaj ryzyka wyłącznie zapachem.","Zapach nie wyklucza zagrożenia mikrobiologicznego. W tej sytuacji decyduje termin „należy spożyć do”.","Tak — Nie używam mięsa po tej dacie, nawet jeśli wygląda poprawnie."],"question":"Która decyzja jest właściwa po upływie terminu „należy spożyć do”?","situation":"W lodówce jest surowe mięso dzień po dacie „należy spożyć do”.","explanation":"Plan zakupów i ustawienie produktów w lodówce pomagają ograniczać wyrzucanie żywności. „Najlepiej spożyć przed” opisuje jakość, a „należy spożyć do” odnosi się do bezpieczeństwa. Produktu po terminie „należy spożyć do” nie spożywaj; nie oceniaj ryzyka wyłącznie zapachem."}}$data$::jsonb),
 ('jestem-eko',15,$data${"learning":{"task":"Powiedz Anielce, jak zastosujesz tę zasadę u siebie: Przerywam dodawanie niedozwolonych resztek i poprawiam proces według instrukcji.","intro":"Kompostowanie wymaga dostępu powietrza, odpowiedniej wilgotności i prawidłowego doboru składników. Mięso, tłuszcze i inne odpadki mogą przyciągać szkodniki w typowych przydomowych kompostownikach. Nie każdy system domowy przyjmuje wszystkie bioodpady.","correct":0,"example":"Przerywam dodawanie niedozwolonych resztek i poprawiam proces według instrukcji.","options":["Przerywam dodawanie niedozwolonych resztek i poprawiam proces według instrukcji.","Dodaję więcej mięsa, aby przyspieszyć rozkład.","Przykryję mięso większą ilością suchych liści i będę dodawać resztki tak jak wcześniej."],"feedback":["Tak — Przerywam dodawanie niedozwolonych resztek i poprawiam proces według instrukcji.","To nie jest właściwe. Kompostowanie wymaga dostępu powietrza, odpowiedniej wilgotności i prawidłowego doboru składników. Mięso, tłuszcze i inne odpadki mogą przyciągać szkodniki w typowych przydomowych kompostownikach. Nie każdy system domowy przyjmuje wszystkie bioodpady.","Trzeba zmienić dobór wsadu według zasad bezpiecznego kompostowania i wyjaśnić przyczynę problemu."],"question":"Co zrobisz, kiedy kompost przyciąga gryzonie?","situation":"Do kompostu wrzucano mięso, pojawiły się szczury.","explanation":"Kompostowanie wymaga dostępu powietrza, odpowiedniej wilgotności i prawidłowego doboru składników. Mięso, tłuszcze i inne odpadki mogą przyciągać szkodniki w typowych przydomowych kompostownikach. Nie każdy system domowy przyjmuje wszystkie bioodpady."}}$data$::jsonb),
 ('jestem-eko',16,$data${"learning":{"task":"Powiedz Anielce, jak zastosujesz tę zasadę u siebie: Sprawdzam oznaczenie i oddaję do punktu zwrotu.","intro":"Systemy kaucyjne obejmują konkretne oznakowane opakowania. W Polsce od października 2025 r. działa system dla wybranych butelek i puszek. Opakowanie z kaucją oddawaj do właściwego punktu; nie każde szkło czy tworzywo podlega temu samemu systemowi.","correct":1,"example":"Sprawdzam oznaczenie i oddaję do punktu zwrotu.","options":["Zgniotę butelkę na płasko przed oddaniem, żeby zajęła mniej miejsca w torbie.","Sprawdzam oznaczenie i oddaję do punktu zwrotu.","Wrzucam butelkę do zmieszanych, mimo dostępnego zwrotu."],"feedback":["Punkt zwrotu musi rozpoznać opakowanie. Zostaw je niezgniecione i z czytelną etykietą.","Tak — Sprawdzam oznaczenie i oddaję do punktu zwrotu.","To nie jest właściwe. Systemy kaucyjne obejmują konkretne oznakowane opakowania. W Polsce od października 2025 r. działa system dla wybranych butelek i puszek. Opakowanie z kaucją oddawaj do właściwego punktu; nie każde szkło czy tworzywo podlega temu samemu systemowi."],"question":"Jak przygotujesz oznaczoną butelkę do zwrotu?","situation":"Masz pustą butelkę z etykietą systemu kaucyjnego.","explanation":"Systemy kaucyjne obejmują konkretne oznakowane opakowania. W Polsce od października 2025 r. działa system dla wybranych butelek i puszek. Opakowanie z kaucją oddawaj do właściwego punktu; nie każde szkło czy tworzywo podlega temu samemu systemowi."}}$data$::jsonb),
 ('jestem-eko',17,$data${"learning":{"task":"Powiedz Anielce, jak zastosujesz tę zasadę u siebie: Sprawdzam uszczelkę i możliwość bezpiecznej naprawy, nie wyłączam chłodzenia żywności.","intro":"Ogrzewanie, stan izolacji, temperatura pomieszczeń i działanie urządzeń mogą znacząco zmieniać zużycie energii. Decyzje najlepiej opierać na odczycie licznika i realnym komforcie. Przy instalacjach elektrycznych i chłodniczych nie podejmuj samodzielnie ryzykownych napraw.","correct":2,"example":"Sprawdzam uszczelkę i możliwość bezpiecznej naprawy, nie wyłączam chłodzenia żywności.","options":["Odłączam lodówkę na noc z pełną zawartością.","Podniosę temperaturę bez sprawdzania przechowywanej żywności i założę, że to załatwia problem uszczelki.","Sprawdzam uszczelkę i możliwość bezpiecznej naprawy, nie wyłączam chłodzenia żywności."],"feedback":["To nie jest właściwe. Ogrzewanie, stan izolacji, temperatura pomieszczeń i działanie urządzeń mogą znacząco zmieniać zużycie energii. Decyzje najlepiej opierać na odczycie licznika i realnym komforcie. Przy instalacjach elektrycznych i chłodniczych nie podejmuj samodzielnie ryzykownych napraw.","Najpierw sprawdź przyczynę częstego uruchamiania. Zachowaj warunki chłodzenia żywności i oceń naprawę.","Tak — Sprawdzam uszczelkę i możliwość bezpiecznej naprawy, nie wyłączam chłodzenia żywności."],"question":"Od czego zaczniesz kontrolę zużycia energii przez lodówkę?","situation":"Lodówka ma uszkodzoną uszczelkę i stale się załącza.","explanation":"Ogrzewanie, stan izolacji, temperatura pomieszczeń i działanie urządzeń mogą znacząco zmieniać zużycie energii. Decyzje najlepiej opierać na odczycie licznika i realnym komforcie. Przy instalacjach elektrycznych i chłodniczych nie podejmuj samodzielnie ryzykownych napraw."}}$data$::jsonb),
 ('jestem-eko',18,$data${"learning":{"task":"Powiedz Anielce, jak zastosujesz tę zasadę u siebie: Zgłaszam lub naprawiam nieszczelność bez ryzykownej ingerencji.","intro":"Nieszczelny kran może marnować wodę przez wiele godzin. Zmywarka i pralka powinny działać zgodnie z instrukcją oraz rzeczywistą potrzebą. Oszczędzanie nie uzasadnia zaniedbania higieny ani wylewania chemikaliów do odpływu.","correct":0,"example":"Zgłaszam lub naprawiam nieszczelność bez ryzykownej ingerencji.","options":["Zgłaszam lub naprawiam nieszczelność bez ryzykownej ingerencji.","Ignoruję wyciek, bo woda jest odnawialna.","Poczekam, aż miesięczny rachunek wyraźnie wzrośnie, żeby upewnić się, że wyciek istnieje."],"feedback":["Tak — Zgłaszam lub naprawiam nieszczelność bez ryzykownej ingerencji.","To nie jest właściwe. Nieszczelny kran może marnować wodę przez wiele godzin. Zmywarka i pralka powinny działać zgodnie z instrukcją oraz rzeczywistą potrzebą. Oszczędzanie nie uzasadnia zaniedbania higieny ani wylewania chemikaliów do odpływu.","Widoczny wyciek wystarcza, by go zgłosić albo sprawdzić możliwość bezpiecznej naprawy."],"question":"Jak ograniczysz straty wody z kapiącego kranu?","situation":"Kran cieknie od tygodni, ale rachunki są niskie.","explanation":"Nieszczelny kran może marnować wodę przez wiele godzin. Zmywarka i pralka powinny działać zgodnie z instrukcją oraz rzeczywistą potrzebą. Oszczędzanie nie uzasadnia zaniedbania higieny ani wylewania chemikaliów do odpływu."}}$data$::jsonb),
 ('jestem-eko',19,$data${"learning":{"task":"Powiedz Anielce, jak zastosujesz tę zasadę u siebie: Sprawdzam przyczyny i ewentualną naprawę przed zakupem nowego.","intro":"Wytworzenie elektroniki wymaga surowców i energii. Aktualizacje, naprawy i bezpieczna wymiana podzespołów mogą przedłużyć czas użytkowania. Przed sprzedażą lub oddaniem sprzętu wykonaj kopię i usuń prywatne dane; nie porzucaj urządzeń w odpadach zmieszanych.","correct":1,"example":"Sprawdzam przyczyny i ewentualną naprawę przed zakupem nowego.","options":["Kupuję nowy, a powolny start traktuję jako dowód uszkodzenia całego urządzenia.","Sprawdzam przyczyny i ewentualną naprawę przed zakupem nowego.","Kupuję nowy bez sprawdzenia przyczyny spowolnienia."],"feedback":["Wolne uruchamianie może wynikać z wielu przyczyn. Diagnostyka pomaga ocenić sens aktualizacji lub naprawy.","Tak — Sprawdzam przyczyny i ewentualną naprawę przed zakupem nowego.","To nie jest właściwe. Wytworzenie elektroniki wymaga surowców i energii. Aktualizacje, naprawy i bezpieczna wymiana podzespołów mogą przedłużyć czas użytkowania. Przed sprzedażą lub oddaniem sprzętu wykonaj kopię i usuń prywatne dane; nie porzucaj urządzeń w odpadach zmieszanych."],"question":"Co zrobisz przed wymianą wolno działającego laptopa?","situation":"Laptop uruchamia się wolno, choć działa i nadaje się do pracy.","explanation":"Wytworzenie elektroniki wymaga surowców i energii. Aktualizacje, naprawy i bezpieczna wymiana podzespołów mogą przedłużyć czas użytkowania. Przed sprzedażą lub oddaniem sprzętu wykonaj kopię i usuń prywatne dane; nie porzucaj urządzeń w odpadach zmieszanych."}}$data$::jsonb),
 ('jestem-eko',20,$data${"learning":{"task":"Powiedz Anielce, jak zastosujesz tę zasadę u siebie: Rozważam spacer lub połączenie zakupów z innymi zadaniami.","intro":"Spacer, rower czy transport zbiorowy mogą zmniejszać zużycie paliwa przy odpowiednich warunkach. Wybór powinien uwzględniać bezpieczeństwo, pogodę, dostępność i zdrowie. Nie obwiniaj osób, dla których auto jest konieczne; szukaj realnych zmian.","correct":2,"example":"Rozważam spacer lub połączenie zakupów z innymi zadaniami.","options":["Wybieram auto zawsze, nawet gdy spacer byłby bezpieczny i wygodny.","Wybiorę samochód dla każdego pojedynczego zakupu, bo odległość jest krótka.","Rozważam spacer lub połączenie zakupów z innymi zadaniami."],"feedback":["To nie jest właściwe. Spacer, rower czy transport zbiorowy mogą zmniejszać zużycie paliwa przy odpowiednich warunkach. Wybór powinien uwzględniać bezpieczeństwo, pogodę, dostępność i zdrowie. Nie obwiniaj osób, dla których auto jest konieczne; szukaj realnych zmian.","Przy bezpiecznej trasie i niewielkim ładunku można rozważyć spacer lub połączenie kilku spraw w jednym wyjściu.","Tak — Rozważam spacer lub połączenie zakupów z innymi zadaniami."],"question":"Jak wybierzesz sposób dotarcia do sklepu w tej sytuacji?","situation":"Masz bezpieczną drogę pieszą do sklepu oddalonego o 600 metrów.","explanation":"Spacer, rower czy transport zbiorowy mogą zmniejszać zużycie paliwa przy odpowiednich warunkach. Wybór powinien uwzględniać bezpieczeństwo, pogodę, dostępność i zdrowie. Nie obwiniaj osób, dla których auto jest konieczne; szukaj realnych zmian."}}$data$::jsonb),
 ('jestem-eko',21,$data${"learning":{"task":"Powiedz Anielce, jak zastosujesz tę zasadę u siebie: Wstrzymuję prace przy materiale i kieruję sprawę do uprawnionych specjalistów.","intro":"Czyste drewno, metale, gruz, impregnaty, farby i materiały z substancjami niebezpiecznymi wymagają różnych sposobów zbiórki. Materiał podejrzany o azbest pozostaw bez naruszania i zleć fachową ocenę. Nie próbuj recyklingu przez przypadkowe mieszanie odpadów.","correct":0,"example":"Wstrzymuję prace przy materiale i kieruję sprawę do uprawnionych specjalistów.","options":["Wstrzymuję prace przy materiale i kieruję sprawę do uprawnionych specjalistów.","Łamię płytę, aby zmieściła się w worku.","Przytnę mały fragment, żeby samodzielnie porównać wnętrze płyty z ilustracją."],"feedback":["Tak — Wstrzymuję prace przy materiale i kieruję sprawę do uprawnionych specjalistów.","To nie jest właściwe. Czyste drewno, metale, gruz, impregnaty, farby i materiały z substancjami niebezpiecznymi wymagają różnych sposobów zbiórki. Materiał podejrzany o azbest pozostaw bez naruszania i zleć fachową ocenę. Nie próbuj recyklingu przez przypadkowe mieszanie odpadów.","Naruszenie podejrzanego materiału może uwolnić szkodliwy pył. Wstrzymaj pracę przy nim i zorganizuj ocenę specjalisty."],"question":"Co zrobisz po znalezieniu podejrzanej płyty w starym budynku?","situation":"W starym budynku znaleziono podejrzaną płytę izolacyjną.","explanation":"Czyste drewno, metale, gruz, impregnaty, farby i materiały z substancjami niebezpiecznymi wymagają różnych sposobów zbiórki. Materiał podejrzany o azbest pozostaw bez naruszania i zleć fachową ocenę. Nie próbuj recyklingu przez przypadkowe mieszanie odpadów."}}$data$::jsonb),
 ('jestem-eko',22,$data${"learning":{"task":"Powiedz Anielce, jak zastosujesz tę zasadę u siebie: Analizuję możliwość łączenia zamówień i opakowań zwrotnych.","intro":"Konsolidacja dostaw, opakowania zwrotne i prawidłowe zabezpieczenie produktów mogą ograniczyć straty. Nie wymuszaj redukcji opakowania kosztem uszkodzonego towaru. Porównuj rzeczywisty wpływ, terminy i liczbę przewozów.","correct":1,"example":"Analizuję możliwość łączenia zamówień i opakowań zwrotnych.","options":["Zamienię karton na inne jednorazowe opakowanie bez sprawdzenia wielkości i częstotliwości wysyłek.","Analizuję możliwość łączenia zamówień i opakowań zwrotnych.","Zlecam pięć kolejnych dostaw tylko dlatego, że transport opisano jako zielony."],"feedback":["Wielkość partii i liczba dostaw mogą wpływać na ilość odpadów. Porównaj je wraz z możliwością obiegu opakowań.","Tak — Analizuję możliwość łączenia zamówień i opakowań zwrotnych.","To nie jest właściwe. Konsolidacja dostaw, opakowania zwrotne i prawidłowe zabezpieczenie produktów mogą ograniczyć straty. Nie wymuszaj redukcji opakowania kosztem uszkodzonego towaru. Porównuj rzeczywisty wpływ, terminy i liczbę przewozów."],"question":"Co zbadasz w pierwszej kolejności przy codziennych małych dostawach?","situation":"Firma sprowadza codziennie małą paczkę od jednego dostawcy.","explanation":"Konsolidacja dostaw, opakowania zwrotne i prawidłowe zabezpieczenie produktów mogą ograniczyć straty. Nie wymuszaj redukcji opakowania kosztem uszkodzonego towaru. Porównuj rzeczywisty wpływ, terminy i liczbę przewozów."}}$data$::jsonb),
 ('jestem-eko',23,$data${"learning":{"task":"Powiedz Anielce, jak zastosujesz tę zasadę u siebie: Proszę o konkretny zakres deklaracji i wiarygodne dowody.","intro":"Sformułowania „100% eko” lub „przyjazny planecie” wymagają konkretnego, sprawdzalnego znaczenia. Pytaj o parametry, zakres całego produktu, źródła badań i niezależną ocenę. Certyfikat może dotyczyć tylko jednego etapu lub składnika, nie wszystkiego.","correct":2,"example":"Proszę o konkretny zakres deklaracji i wiarygodne dowody.","options":["Wierzę bez weryfikacji, bo logo ma zielony kolor.","Przyjmę hasło za sprawdzone, jeśli obok niego znajduje się zielona pieczątka bez wyjaśnienia.","Proszę o konkretny zakres deklaracji i wiarygodne dowody."],"feedback":["To nie jest właściwe. Sformułowania „100% eko” lub „przyjazny planecie” wymagają konkretnego, sprawdzalnego znaczenia. Pytaj o parametry, zakres całego produktu, źródła badań i niezależną ocenę. Certyfikat może dotyczyć tylko jednego etapu lub składnika, nie wszystkiego.","Przydatna deklaracja określa zakres i przedstawia dane, które można sprawdzić.","Tak — Proszę o konkretny zakres deklaracji i wiarygodne dowody."],"question":"Jaki dowód jest potrzebny do sprawdzenia deklaracji środowiskowej?","situation":"Reklama twierdzi, że produkt jest w pełni neutralny dla planety, ale nie podaje danych.","explanation":"Sformułowania „100% eko” lub „przyjazny planecie” wymagają konkretnego, sprawdzalnego znaczenia. Pytaj o parametry, zakres całego produktu, źródła badań i niezależną ocenę. Certyfikat może dotyczyć tylko jednego etapu lub składnika, nie wszystkiego."}}$data$::jsonb),
 ('jestem-eko',24,$data${"learning":{"task":"Powiedz Anielce, jak zastosujesz tę zasadę u siebie: Sprawdzam, co można kupować rzadziej lub łączyć dostawy.","intro":"Przez tydzień zapisuj typ i przyczynę odpadów: opakowania, resztki żywności, tekstylia i inne. Nie dotykaj odpadów niebezpiecznych, aby je ważyć. Największa frakcja nie zawsze wskazuje największy wpływ, ale dane pomogą znaleźć priorytet.","correct":0,"example":"Sprawdzam, co można kupować rzadziej lub łączyć dostawy.","options":["Sprawdzam, co można kupować rzadziej lub łączyć dostawy.","Kupuję drogie pojemniki, żeby schować problem przed domownikami.","Zmienię miejsce kosza i uznam problem za rozwiązany, zanim porównam liczbę dostaw."],"feedback":["Tak — Sprawdzam, co można kupować rzadziej lub łączyć dostawy.","To nie jest właściwe. Przez tydzień zapisuj typ i przyczynę odpadów: opakowania, resztki żywności, tekstylia i inne. Nie dotykaj odpadów niebezpiecznych, aby je ważyć. Największa frakcja nie zawsze wskazuje największy wpływ, ale dane pomogą znaleźć priorytet.","Wyniki audytu wskazują źródło odpadu. Sprawdź, jak zmniejszyć liczbę przesyłek, i powtórz pomiar."],"question":"Jaki wniosek warto sprawdzić po tygodniu obserwacji kosza?","situation":"Po tygodniu okazuje się, że najczęściej wyrzucasz opakowania po zakupach internetowych.","explanation":"Przez tydzień zapisuj typ i przyczynę odpadów: opakowania, resztki żywności, tekstylia i inne. Nie dotykaj odpadów niebezpiecznych, aby je ważyć. Największa frakcja nie zawsze wskazuje największy wpływ, ale dane pomogą znaleźć priorytet."}}$data$::jsonb),
 ('jestem-eko',25,$data${"learning":{"task":"Powiedz Anielce, jak zastosujesz tę zasadę u siebie: Wybieram bezpłatne lub tanie zmiany i mierzę wynik bez zadłużania się.","intro":"Nie potrzebujesz absolutnego zera odpadów, żeby działać skutecznie. Wybierz trzy realne zmiany, przypisz im mierniki i sprawdź wyniki po miesiącu. Bezpieczeństwo i finanse są ważniejsze niż wygląd zielonego stylu życia.","correct":1,"example":"Wybieram bezpłatne lub tanie zmiany i mierzę wynik bez zadłużania się.","options":["Kupię cały zestaw nowych urządzeń na raty, zanim policzę oszczędności.","Wybieram bezpłatne lub tanie zmiany i mierzę wynik bez zadłużania się.","Biorę wysoki kredyt tylko po to, by kupić modne urządzenia."],"feedback":["Najpierw wybierz zmiany o małym koszcie i mierz ich skutki. Decyzję o zakupach podejmiesz z większą wiedzą.","Tak — Wybieram bezpłatne lub tanie zmiany i mierzę wynik bez zadłużania się.","To nie jest właściwe. Nie potrzebujesz absolutnego zera odpadów, żeby działać skutecznie. Wybierz trzy realne zmiany, przypisz im mierniki i sprawdź wyniki po miesiącu. Bezpieczeństwo i finanse są ważniejsze niż wygląd zielonego stylu życia."],"question":"Jak zacząć plan przy ograniczonym budżecie?","situation":"Masz ograniczony budżet i nie możesz wymienić wszystkich urządzeń.","explanation":"Nie potrzebujesz absolutnego zera odpadów, żeby działać skutecznie. Wybierz trzy realne zmiany, przypisz im mierniki i sprawdź wyniki po miesiącu. Bezpieczeństwo i finanse są ważniejsze niż wygląd zielonego stylu życia."}}$data$::jsonb),
 ('jestem-eko',26,$data${"learning":{"task":"Powiedz Anielce, jak zastosujesz tę zasadę u siebie: Pytam o liczbę użyć i rzeczywiste dane, nie ogłaszam zasady bez wyjątków.","intro":"Porównanie torby materiałowej i jednorazowej lub kubka wielorazowego wymaga danych o produkcji, liczbie użyć, myciu, trwałości i końcu życia. Bez tych danych nie da się odpowiedzialnie ogłosić uniwersalnego zwycięzcy. Lepiej pokazać niepewność niż wymyślony próg użyć.","correct":2,"example":"Pytam o liczbę użyć i rzeczywiste dane, nie ogłaszam zasady bez wyjątków.","options":["Potwierdzam wyłącznie dlatego, że materiał jest naturalny.","Ocenię wyłącznie wagę pustej torby, niezależnie od materiału i liczby użyć.","Pytam o liczbę użyć i rzeczywiste dane, nie ogłaszam zasady bez wyjątków."],"feedback":["To nie jest właściwe. Porównanie torby materiałowej i jednorazowej lub kubka wielorazowego wymaga danych o produkcji, liczbie użyć, myciu, trwałości i końcu życia. Bez tych danych nie da się odpowiedzialnie ogłosić uniwersalnego zwycięzcy. Lepiej pokazać niepewność niż wymyślony próg użyć.","Rzetelne porównanie dotyczy tej samej funkcji. Uwzględnij trwałość, rzeczywistą liczbę użyć i koniec życia produktu.","Tak — Pytam o liczbę użyć i rzeczywiste dane, nie ogłaszam zasady bez wyjątków."],"question":"Co porównasz, gdy wybierasz między dwoma typami torby?","situation":"Ktoś stwierdza, że każda bawełniana torba jest zawsze lepsza od plastikowej.","explanation":"Porównanie torby materiałowej i jednorazowej lub kubka wielorazowego wymaga danych o produkcji, liczbie użyć, myciu, trwałości i końcu życia. Bez tych danych nie da się odpowiedzialnie ogłosić uniwersalnego zwycięzcy. Lepiej pokazać niepewność niż wymyślony próg użyć."}}$data$::jsonb),
 ('jestem-eko',27,$data${"learning":{"task":"Powiedz Anielce, jak zastosujesz tę zasadę u siebie: Ustawiam bezpieczny punkt zbiórki i wyjaśniam jego użycie.","intro":"Działający system wymaga czytelnych pojemników, lokalnej instrukcji, odpowiedzialności i sposobu wyjaśniania pomyłek. Zmiany utrzymują się lepiej, gdy ludzie rozumieją powód i mają warunki do właściwego wyboru. Jedna kartka wskazówek bywa lepsza niż setka zakazów.","correct":0,"example":"Ustawiam bezpieczny punkt zbiórki i wyjaśniam jego użycie.","options":["Ustawiam bezpieczny punkt zbiórki i wyjaśniam jego użycie.","Publicznie zawstydzam pracownika bez przygotowania rozwiązania.","Wyślę przypomnienie, ale pozostawię miejsce zbiórki i odpowiedzialność bez ustaleń."],"feedback":["Tak — Ustawiam bezpieczny punkt zbiórki i wyjaśniam jego użycie.","To nie jest właściwe. Działający system wymaga czytelnych pojemników, lokalnej instrukcji, odpowiedzialności i sposobu wyjaśniania pomyłek. Zmiany utrzymują się lepiej, gdy ludzie rozumieją powód i mają warunki do właściwego wyboru. Jedna kartka wskazówek bywa lepsza niż setka zakazów.","Jasne miejsce, zasady odbioru i informacja pozwalają przełożyć dobrą intencję na działanie."],"question":"Jak ułatwisz właściwy zwrot baterii w biurze?","situation":"W biurze baterie trafiają do resztkowych, bo nikt nie wie, gdzie je oddać.","explanation":"Działający system wymaga czytelnych pojemników, lokalnej instrukcji, odpowiedzialności i sposobu wyjaśniania pomyłek. Zmiany utrzymują się lepiej, gdy ludzie rozumieją powód i mają warunki do właściwego wyboru. Jedna kartka wskazówek bywa lepsza niż setka zakazów."}}$data$::jsonb),
 ('jestem-eko',28,$data${"learning":{"task":"Powiedz Anielce, jak zastosujesz tę zasadę u siebie: Wyznaczam osobę, miejsce i datę przeglądu oraz informuję wszystkich spokojnie.","intro":"Przygotuj prostą tabelę: co jest wyrzucane, z jakiej przyczyny, jaki jest lepszy wybór, kto go wykona i kiedy sprawdzimy wynik. Ustal jeden miernik na frakcję, nie obciążając domowników skomplikowanym raportowaniem. Zostaw miejsce na korektę planu.","correct":1,"example":"Wyznaczam osobę, miejsce i datę przeglądu oraz informuję wszystkich spokojnie.","options":["Zmienię nazwę projektu, a ustalenia o osobie odpowiedzialnej przekażę ustnie tylko jednej zmianie.","Wyznaczam osobę, miejsce i datę przeglądu oraz informuję wszystkich spokojnie.","Pozwalam, by odpady niebezpieczne trafiały do dowolnego pojemnika."],"feedback":["Potrzebne są czytelna odpowiedzialność, miejsce i termin przeglądu dostępne dla wszystkich zmian.","Tak — Wyznaczam osobę, miejsce i datę przeglądu oraz informuję wszystkich spokojnie.","To nie jest właściwe. Przygotuj prostą tabelę: co jest wyrzucane, z jakiej przyczyny, jaki jest lepszy wybór, kto go wykona i kiedy sprawdzimy wynik. Ustal jeden miernik na frakcję, nie obciążając domowników skomplikowanym raportowaniem. Zostaw miejsce na korektę planu."],"question":"Co sprawi, że projekt będzie działał po pierwszym tygodniu?","situation":"W projekcie ekologicznym nikt nie pamięta, kto odpowiada za zbiórkę baterii.","explanation":"Przygotuj prostą tabelę: co jest wyrzucane, z jakiej przyczyny, jaki jest lepszy wybór, kto go wykona i kiedy sprawdzimy wynik. Ustal jeden miernik na frakcję, nie obciążając domowników skomplikowanym raportowaniem. Zostaw miejsce na korektę planu."}}$data$::jsonb),
 ('jestem-eko',29,$data${"learning":{"task":"Powiedz Anielce, jak zastosujesz tę zasadę u siebie: Kurtkę rozważam do naprawy, butelkę oddaję w systemie kaucji, baterię do specjalnej zbiórki.","intro":"Znajomość kolorów koszy to początek, nie koniec. Na poziomie Expert umiesz rozdzielić potrzebę od zakupu, naprawić albo oddać rzeczy, wyjaśnić recykling, rozpoznać odpady niebezpieczne i sprawdzić lokalną instrukcję. Jeśli brakuje danych, potrafisz powiedzieć, co należy zweryfikować.","correct":2,"example":"Kurtkę rozważam do naprawy, butelkę oddaję w systemie kaucji, baterię do specjalnej zbiórki.","options":["Wrzucam wszystkie trzy do pojemnika na plastik.","Odłożę kurtkę i baterię do jednego worka odpadów, a butelkę zwrócę tylko wtedy, gdy znajdę paragon.","Kurtkę rozważam do naprawy, butelkę oddaję w systemie kaucji, baterię do specjalnej zbiórki."],"feedback":["To nie jest właściwe. Znajomość kolorów koszy to początek, nie koniec. Na poziomie Expert umiesz rozdzielić potrzebę od zakupu, naprawić albo oddać rzeczy, wyjaśnić recykling, rozpoznać odpady niebezpieczne i sprawdzić lokalną instrukcję. Jeśli brakuje danych, potrafisz powiedzieć, co należy zweryfikować.","Każdy przedmiot ma inną drogę. Sprawdź naprawę, oznakowanie kaucji i oddzielną zbiórkę baterii.","Tak — Kurtkę rozważam do naprawy, butelkę oddaję w systemie kaucji, baterię do specjalnej zbiórki."],"question":"Jak postąpisz z trzema przedmiotami z zadania?","situation":"Masz kurtkę z zepsutym zamkiem, butelkę z kaucją i rozładowaną baterię.","explanation":"Znajomość kolorów koszy to początek, nie koniec. Na poziomie Expert umiesz rozdzielić potrzebę od zakupu, naprawić albo oddać rzeczy, wyjaśnić recykling, rozpoznać odpady niebezpieczne i sprawdzić lokalną instrukcję. Jeśli brakuje danych, potrafisz powiedzieć, co należy zweryfikować."}}$data$::jsonb)
)
update public.ta_lessons l set material=l.material||c.patch,updated_at=now()
from changes c where l.course_slug=c.course_slug and l.lesson_no=c.lesson_no and not (l.material @> c.patch);
